"""
A-Share Paper Trading Skill Module
=================================

Complete paper trading simulation engine for A-share stocks.
This module provides:
- PaperTradingEngine: Manages virtual portfolio with proper A-share mechanics
- MomentumValueStrategy: Implements momentum-value hybrid trading strategy
- BacktestRunner: Runs strategies against historical market data

A-Share Rules Implemented:
- T+1 settlement (can't sell shares bought today until next trading day)
- Minimum lot size of 100 shares for buy orders
- Price limit validation (10% main board, 20% ChiNext/STAR, 5% ST stocks)
- Accurate fee calculation (commission, stamp tax, transfer fee)
"""

import json
import yaml
import os
from datetime import datetime, timedelta
from dataclasses import dataclass, field
from typing import Optional, Dict, List, Any, Tuple, Set
import pandas as pd
import numpy as np


# ============================================================================
# Data Structures
# ============================================================================

@dataclass
class Position:
    """Represents a stock position in the portfolio."""
    stock_code: str
    shares: int = 0
    avg_cost: float = 0.0
    current_price: float = 0.0
    purchased_date: str = ""
    bought_today: bool = False

    def calc_avg_price(self, new_price: float, shares_buy: int, shares_own: int) -> float:
        """Calculate new average cost after a purchase."""
        if shares_buy == 0:
            return self.avg_cost
        total_cost = (self.avg_cost * shares_own + new_price * shares_buy)
        return total_cost / (shares_own + shares_buy)

    def to_dict(self) -> Dict:
        return {
            'stock_code': self.stock_code,
            'shares': self.shares,
            'avg_cost': round(self.avg_cost, 2),
            'current_price': round(self.current_price, 2),
            'purchased_date': self.purchased_date,
            'bought_today': self.bought_today
        }


@dataclass
class Trade:
    """Represents a trade execution."""
    trade_id: str
    stock_code: str
    side: str
    shares: int
    fill_price: float
    fill_date: str
    fill_time: str
    amount: float
    commission: float
    stamp_tax: float
    transfer_fee: float
    total_cost: float
    order_type: str
    status: str
    reason: str = ""
    net_amount: float = 0.0

    def to_dict(self) -> Dict:
        return {
            'trade_id': self.trade_id,
            'stock_code': self.stock_code,
            'side': self.side,
            'shares': self.shares,
            'fill_price': round(self.fill_price, 2),
            'fill_date': self.fill_date,
            'fill_time': self.fill_time,
            'amount': round(self.amount, 2),
            'commission': round(self.commission, 2),
            'stamp_tax': round(self.stamp_tax, 2),
            'transfer_fee': round(self.transfer_fee, 2),
            'total_cost': round(self.total_cost, 2),
            'order_type': self.order_type,
            'status': self.status,
            'reason': self.reason,
            'net_amount': round(self.net_amount, 2)
        }


@dataclass
class Portfolio:
    """Represents the trading account/portfolio."""
    cash: float = 1000000.0
    trades: List[Trade] = field(default_factory=list)
    last_trade_date: str = ""
    positions: Dict[str, Position] = field(default_factory=dict)
    initial_capital: float = 1000000.0

    def add_trade(self, trade: Trade):
        self.trades.append(trade)

    def get_shares_value(self, prices: Dict[str, float]) -> float:
        """Calculate current value of shares held."""
        total = 0.0
        for pos in self.positions.values():
            if pos.stock_code in prices and prices[pos.stock_code] > 0:
                total += pos.shares * prices[pos.stock_code]
        return total

    def get_total_equity(self, prices: Dict[str, float]) -> float:
        return self.cash + self.get_shares_value(prices)

    def get_initial_equity(self) -> float:
        return self.initial_capital

    def get_available_cash(self) -> float:
        """Get cash available for buying (excluding T+1 unsettled purchases)."""
        available = 0.0
        today = self.last_trade_date
        for trade in self.trades:
            if trade.fill_date == today and trade.side == 'sell' and trade.status == 'filled':
                available += trade.net_amount
            elif trade.fill_date != today and trade.side == 'buy' and trade.status == 'filled':
                # Funds from buys before today are available
                available += trade.net_amount
        return self.cash + available


# ============================================================================
# Helper Functions
# ============================================================================

def load_json_file(filepath: str) -> Any:
    with open(filepath, 'r', encoding='utf-8') as f:
        return json.load(f)


def load_yaml_file(filepath: str) -> Any:
    with open(filepath, 'r', encoding='utf-8') as f:
        return yaml.safe_load(f)


def parse_date(date_str: str) -> datetime:
    try:
        return datetime.strptime(date_str, '%Y-%m-%d')
    except:
        return None


def format_date(dt: datetime) -> str:
    return dt.strftime('%Y-%m-%d') if dt else ""


def round_to_tick(price: float, tick_size: float = 0.01) -> float:
    return round(price / tick_size) * tick_size


def calculate_limit_price(prev_close: float, limit_percent: float, is_up: bool = True) -> float:
    """Calculate limit price based on previous close and limit percentage."""
    if is_up:
        limit = prev_close * (1 + limit_percent / 100)
    else:
        limit = prev_close * (1 - limit_percent / 100)
    return round_to_tick(limit)


# ============================================================================
# Fee Calculator
# ============================================================================

class FeeCalculator:
    """Calculate A-share trading fees."""

    def __init__(self, fees_config: Dict):
        self.commission_rate = fees_config.get('commission_rate', 0.00025)
        self.commission_min = fees_config.get('commission_min_amount', 5.0)
        self.stamp_tax_rate = fees_config.get('stamp_tax_rate', 0.001)
        self.transfer_fee_rate = fees_config.get('transfer_fee_rate', 0.00002)

    def calculate_trade_cost(self, side: str, price: float, shares: int) -> float:
        """Calculate total cost for a trade (commission + stamp tax + transfer fee)."""
        trade_amount = price * shares

        # Commission
        commission = trade_amount * self.commission_rate
        if commission < self.commission_min:
            commission = self.commission_min

        # Stamp tax (sell only)
        stamp_tax = 0.0
        if side == 'sell':
            stamp_tax = trade_amount * self.stamp_tax_rate

        # Transfer fee
        transfer_fee = trade_amount * self.transfer_fee_rate

        total = commission + stamp_tax + transfer_fee
        return total

    def get_buy_cost(self, price: float, shares: int) -> float:
        """Get total cost to buy shares."""
        cost = self.calculate_trade_cost('buy', price, shares)
        return price * shares + cost

    def get_sell_proceeds(self, price: float, shares: int) -> float:
        """Get net proceeds from selling shares."""
        cost = self.calculate_trade_cost('sell', price, shares)
        return price * shares - cost


# ============================================================================
# Price Limit Validator
# ============================================================================

class PriceLimitValidator:
    """Validate order price against A-share price limits."""

    # Board to price limit percentage mapping
    BOARD_LIMITS = {
        'main_board': 10.0,      # Shanghai 600/601/603, Shenzhen 000/001
        'chinext': 20.0,         # Shenzhen 300/301
        'star_market': 20.0,     # Shanghai 688
        'st_stocks': 5.0         # ST, *ST stocks
    }

    def __init__(self):
        self.board_limits = self.BOARD_LIMITS.copy()

    def get_board_type(self, stock_code: str) -> str:
        """Determine board type from stock code prefix."""
        if stock_code.startswith('sh600') or stock_code.startswith('sh601') or stock_code.startswith('sh603'):
            return 'main_board'
        elif stock_code.startswith('sh688'):
            return 'star_market'
        elif stock_code.startswith('sz300') or stock_code.startswith('sz301'):
            return 'chinext'
        elif stock_code.startswith('sz000') or stock_code.startswith('sz001') or stock_code.startswith('sz002'):
            return 'main_board'
        elif stock_code.startswith('sz') and not stock_code.startswith('sh'):
            return 'unknown'
        return 'unknown'

    def get_price_limit(self, stock_code: str) -> float:
        """Get price limit percentage for a stock."""
        board = self.get_board_type(stock_code)
        return self.board_limits.get(board, 0.10)

    def check_price_valid(self, stock_code: str, price: float, prev_close: float, is_up: bool) -> Tuple[bool, str]:
        """Check if price is within daily price limit.

        Returns: (is_valid, error_message)
        """
        limit_pct = self.get_price_limit(stock_code)

        if prev_close <= 0:
            return False, "invalid_prev_close"

        if is_up:
            limit = calculate_limit_price(prev_close, limit_pct, is_up=True)
            if price > limit:
                return False, f"price_above_limit({price:.2f} > {limit:.2f})"
        else:
            limit = calculate_limit_price(prev_close, limit_pct, is_up=False)
            if price < limit:
                return False, f"price_below_limit({price:.2f} < {limit:.2f})"

        return True, ""


# ============================================================================
# PaperTradingEngine
# ============================================================================

class PaperTradingEngine:
    """
    Paper trading engine that manages a virtual portfolio with proper A-share mechanics.
    """

    def __init__(self, initial_capital: float = 1000000.0):
        self.initial_capital = initial_capital
        self.portfolio = Portfolio(cash=initial_capital, initial_capital=initial_capital)
        self.stock_list = self._load_stock_list()
        self.fee_calculator = FeeCalculator(load_json_file('config/trading_fees.json'))
        self.price_validator = PriceLimitValidator()

    def _load_stock_list(self) -> Dict[str, Dict]:
        """Load stock reference data from CSV."""
        stock_data = {}
        if os.path.exists('data/reference/stock_list_v2.csv'):
            df = pd.read_csv('data/reference/stock_list_v2.csv', comment='#')
            for _, row in df.iterrows():
                if row['code']:
                    stock_data[row['code']] = {
                        'name': row['name'],
                        'board': row['board'],
                        'lot_size': int(row['lot_size']),
                        'price_limit': float(row['price_limit']) if pd.notna(row['price_limit']) else 0.10
                    }
        return stock_data

    def get_stock_info(self, stock_code: str) -> Optional[Dict]:
        """Get stock information by code."""
        return self.stock_list.get(stock_code)

    def is_trading_day(self, date: str) -> bool:
        """Check if the given date is a trading day (not a holiday)."""
        if date in self._get_holidays():
            return False
        return True

    def _get_holidays(self) -> Set[str]:
        """Get all trading holidays."""
        holidays = set()
        if os.path.exists('data/holidays/cn_trading_holidays_2024.csv'):
            df = pd.read_csv('data/holidays/cn_trading_holidays_2024.csv')
            for _, row in df.iterrows():
                if pd.notna(row['date']):
                    holidays.add(str(row['date']))
        return holidays

    def get_price_on_date(self, stock_code: str, date: str) -> float:
        """Get closing price for a stock on a given date."""
        filepath = f"data/market/{stock_code}_daily.csv"
        if not os.path.exists(filepath):
            return 0.0

        try:
            df = pd.read_csv(filepath)
            mask = df['date'] == date
            if mask.sum() == 0:
                return 0.0
            return float(df.loc[mask, 'close'].values[0])
        except:
            return 0.0

    def get_previous_trading_date(self, date: str, trading_days: List[str] = None) -> Optional[str]:
        """Get the previous trading date."""
        today = parse_date(date)
        if today is None:
            return None

        candidates = set()
        if trading_days:
            for td in trading_days:
                if td < date:
                    candidates.add(td)
        else:
            # Generate candidate dates back in time
            dt = today - timedelta(days=1)
            for _ in range(100):  # Look back 100 days
                dt = dt - timedelta(days=1)
                d = format_date(dt)
                candidates.add(d)

        # Find the most recent trading day
        for cand in sorted(candidates, reverse=True):
            if self.is_trading_day(cand):
                return cand
        return None

    def place_order(
        self,
        stock_code: str,
        side: str,
        price: float,
        shares: int,
        date: str,
        time: str = "09:30",
        order_type: str = "limit"
    ) -> Trade:
        """
        Place an order and execute if conditions are met.

        A-Share Rules:
        - T+1 settlement: Cannot sell shares bought today
        - Minimum lot size: 100 shares for buys
        - Price limits: 10% main board, 20% ChiNext/STAR, 5% ST
        - Max order: 1,000,000 shares
        """
        if side not in ['buy', 'sell']:
            return self._reject_trade("invalid_side", date)

        if not self.is_trading_day(date):
            return self._reject_trade("not_trading_day", date)

        stock_info = self.get_stock_info(stock_code)
        if not stock_info:
            return self._reject_trade("stock_not_found", date)

        # Get previous close price
        prev_close = self.get_price_on_date(stock_code, date)
        if prev_close <= 0:
            # Check if today is the first trading day
            today = parse_date(date)
            first_trade = self._get_first_trading_date(stock_code)
            if first_trade is None or today > parse_date(first_trade):
                prev_close = self.get_previous_trading_date(date, trading_days=[first_trade]) if first_trade else 0.0
                if prev_close <= 0:
                    prev_close = 0.0

        if prev_close == 0:
            return self._reject_trade("unknown_prev_close", date, f"prev_close={prev_close}")

        # Validate price
        is_price_valid, price_error = self.price_validator.check_price_valid(
            stock_code, price, prev_close, side == 'buy'
        )
        if not is_price_valid:
            return self._reject_trade(price_error, date)

        # Validate lot size (buy only)
        if side == 'buy':
            lot_size = stock_info['lot_size']
            if shares % lot_size != 0 or shares < lot_size:
                return self._reject_trade("invalid_lot_size", date, f"shares={shares}, lot_size={lot_size}")

            # Check max order
            max_order = 1000000
            if shares > max_order:
                return self._reject_trade("order_too_large", date, f"shares={shares}, max={max_order}")

        # Check position for sell orders (T+1 rule)
        if side == 'sell':
            can_sell_shares = self._check_can_sell_shares(stock_code, date)
            if can_sell_shares is None:
                return self._reject_trade("t1_settlement", date)
            if can_sell_shares < shares:
                return self._reject_trade("insufficient_shares", date, f"available={can_sell_shares}, requested={shares}")

        # Check funds for buy orders
        if side == 'buy':
            buying_power = self.portfolio.get_available_cash()
            estimated_cost = self.fee_calculator.get_buy_cost(price, shares)
            if buying_power < estimated_cost:
                return self._reject_trade("insufficient_funds", date, f"needed={estimated_cost:.2f}, available={buying_power:.2f}")

        # Calculate actual fill price and costs
        fill_price = price
        if order_type == 'market_order_at_close':
            fill_price = prev_close

        trade_amount = fill_price * shares
        total_cost = self.fee_calculator.get_buy_cost(fill_price, shares) if side == 'buy' else self.fee_calculator.get_sell_proceeds(fill_price, shares)

        net_amount = trade_amount - total_cost
        if side == 'buy':
            net_amount = -total_cost  # Negative means cash out

        trade = Trade(
            trade_id=self._generate_trade_id(),
            stock_code=stock_code,
            side=side,
            shares=shares,
            fill_price=fill_price,
            fill_date=date,
            fill_time=time,
            amount=trade_amount,
            commission=0.0,
            stamp_tax=0.0,
            transfer_fee=0.0,
            total_cost=abs(total_cost),
            order_type=order_type,
            status='filled',
            reason="Order executed successfully",
            net_amount=net_amount
        )

        # Update portfolio
        self._update_portfolio_after_trade(trade, price, shares, side)

        return trade

    def _reject_trade(self, reason: str, date: str, details: str = "") -> Trade:
        """Create a rejected trade."""
        return Trade(
            trade_id=self._generate_trade_id(),
            stock_code=stock_code,
            side=side,
            shares=0,
            fill_price=0.0,
            fill_date=date,
            fill_time="",
            amount=0.0,
            commission=0.0,
            stamp_tax=0.0,
            transfer_fee=0.0,
            total_cost=0.0,
            order_type="limit",
            status='rejected',
            reason=f"{reason}: {details}" if details else reason
        )

    def _get_first_trading_date(self, stock_code: str) -> Optional[str]:
        """Get the first trading date for a stock."""
        filepath = f"data/market/{stock_code}_daily.csv"
        if not os.path.exists(filepath):
            return None

        try:
            df = pd.read_csv(filepath)
            first_date = str(df['date'].iloc[0])
            if self.is_trading_day(first_date):
                return first_date
        except:
            pass
        return None

    def _check_can_sell_shares(self, stock_code: str, date: str) -> Tuple[bool, float]:
        """Check if we can sell shares for a given date (T+1 rule).

        Returns: (can_sell, available_shares) or (False, 0) if cannot sell
        """
        # Check if we own any shares of this stock before today
        today = parse_date(date)
        if today is None:
            return False, 0

        owned_before = 0
        for pos in self.portfolio.positions.values():
            if pos.stock_code == stock_code:
                pos_date = parse_date(pos.purchased_date) if pos.purchased_date else None
                if pos_date is None:
                    owned_before += pos.shares
                elif pos_date < today:
                    owned_before += pos.shares
                else:
                    # Bought today (or same day) - can only sell what was bought today
                    # T+1 rule: wait until next trading day
                    pass

        # If we bought today, we can't sell today (T+1)
        # If we own shares from before, we can sell
        if owned_before > 0:
            return True, owned_before
        else:
            return False, 0

    def _update_portfolio_after_trade(self, trade: Trade, price: float, shares: int, side: str):
        """Update portfolio after a trade is filled."""
        if trade.status != 'filled':
            return

        self.portfolio.last_trade_date = trade.fill_date

        if trade.stock_code in self.stock_list:
            lot_size = self.stock_list[trade.stock_code]['lot_size']

            # Adjust shares to lot size for buys
            adjusted_shares = trade.shares
            if trade.side == 'buy':
                adjusted_shares = (adjusted_shares // lot_size) * lot_size

            if trade.side == 'buy':
                # Deduct cash
                total_cost = self.fee_calculator.get_buy_cost(price, adjusted_shares)
                self.portfolio.cash -= total_cost

                # Update or create position
                if trade.stock_code in self.portfolio.positions:
                    pos = self.portfolio.positions[trade.stock_code]
                    pos.shares += adjusted_shares
                    pos.avg_cost = pos.calc_avg_price(price, adjusted_shares, pos.shares)
                    pos.current_price = price
                else:
                    self.portfolio.positions[trade.stock_code] = Position(
                        stock_code=trade.stock_code,
                        shares=adjusted_shares,
                        avg_cost=price,
                        current_price=price,
                        purchased_date=trade.fill_date,
                        bought_today=True
                    )
            else:
                # Add cash from proceeds
                self.portfolio.cash += price * adjusted_shares

                # Update position
                if trade.stock_code in self.portfolio.positions:
                    pos = self.portfolio.positions[trade.stock_code]
                    pos.shares -= adjusted_shares
                    pos.current_price = price
                    if pos.shares == 0:
                        del self.portfolio.positions[trade.stock_code]

        self.portfolio.add_trade(trade)

    def get_positions_for_date(self, date: str) -> Dict[str, int]:
        """Get available positions on a specific date (T+1 rule applied)."""
        positions = {}
        today = parse_date(date)
        if today is None:
            return positions

        for stock_code, pos in self.portfolio.positions.items():
            pos_date = parse_date(pos.purchased_date) if pos.purchased_date else None

            if pos_date is None or pos_date < today:
                # Owned before today, can sell all
                positions[stock_code] = pos.shares
            else:
                # Bought today or same day, T+1 restriction
                positions[stock_code] = 0  # Cannot sell

        return positions

    def get_available_cash(self) -> float:
        """Calculate cash available for buying."""
        return self.portfolio.cash

    def _generate_trade_id(self) -> str:
        """Generate a unique trade ID."""
        ts = datetime.now().strftime('%Y%m%d%H%M%S')
        import random
        return f"TRD{ts}{random.randint(1000, 9999)}"

    def get_account_summary(self) -> Dict:
        """Get current account summary."""
        prices = {}
        for code, pos in self.portfolio.positions.items():
            prices[code] = pos.current_price

        return {
            'cash': self.portfolio.cash,
            'shares_value': self.portfolio.get_shares_value(prices),
            'total_equity': self.portfolio.get_total_equity(prices),
            'total_trades': len(self.portfolio.trades),
            'positions': self.portfolio.positions
        }

    def reset(self, initial_capital: float = None):
        """Reset the portfolio."""
        capital = initial_capital if initial_capital is not None else self.initial_capital
        self.portfolio = Portfolio(cash=capital, initial_capital=capital)
        self.stock_list = self._load_stock_list()
        self.portfolio.last_trade_date = ""
        self.portfolio.trades = []
        self.portfolio.positions = {}


# ============================================================================
# MomentumValueStrategy
# ============================================================================

class MomentumValueStrategy:
    """
    Momentum-Value Hybrid Strategy

    Strategy logic:
    1. Use moving average crossovers for momentum signals
    2. Consider value metrics (P/E, P/B) for stock selection
    3. Apply risk controls (trailing stop, max loss, drawdown)
    """

    def __init__(self, params: Dict = None):
        self.params = params or {}

        # Strategy selection
        self.ma_periods = self.params.get('stock_selection', {}).get('ma_periods', [5, 10, 20])
        self.volume_threshold = self.params.get('stock_selection', {}).get('volume_threshold', 1.5)
        self.value_metrics = self.params.get('stock_selection', {}).get('value_metrics', ['pe_ratio', 'pb_ratio'])
        self.initial_capital = self.params.get('position_management', {}).get('initial_capital', 1000000)
        self.max_single_position = self.params.get('position_management', {}).get('max_single_position', 0.25)
        self.trailing_stop = self.params.get('stop_loss', {}).get('trailing_stop', 0.08)
        self.fixed_stop = self.params.get('stop_loss', {}).get('fixed_stop', 0.10)
        self.max_drawdown = self.params.get('risk_control', {}).get('max_drawdown', 0.15)
        self.max_daily_loss = self.params.get('risk_control', {}).get('max_daily_loss', 0.03)

    def calculate_ma(self, prices: List[float], period: int) -> List[float]:
        """Calculate moving average."""
        if len(prices) < period:
            return [sum(prices) / len(prices)] if prices else [0.0]
        result = []
        for i in range(len(prices)):
            start_idx = max(0, i - period + 1)
            window = prices[start_idx:i + 1]
            result.append(sum(window) / len(window))
        return result

    def calculate_signals(self, stock_code: str, current_price: float, prices_history: Dict[str, List[float]]) -> Optional[Tuple[str, float]]:
        """
        Generate trading signals based on momentum.

        Returns:
            Tuple of (side, strength) where side is 'buy', 'sell', or None
            strength is 0.0 to 1.0 indicating confidence level
        """
        if stock_code not in prices_history or len(prices_history.get(stock_code, [])) < 20:
            return None, 0.0

        prices = prices_history[stock_code]

        # Calculate short and long MA
        short_period = self.ma_periods[0] if len(self.ma_periods) > 0 else 5
        long_period = self.ma_periods[1] if len(self.ma_periods) > 1 else 20

        short_ma = self.calculate_ma(prices[-short_period:], short_period)[-1] if short_period <= len(prices) else prices[-1]
        long_ma = self.calculate_ma(prices[-long_period:], long_period)[-1] if long_period <= len(prices) else prices[-1]

        # Previous MA values
        prev_short_ma = self.calculate_ma(prices, short_period)[max(0, len(prices) - short_period - 1)]
        prev_long_ma = self.calculate_ma(prices, long_period)[max(0, len(prices) - long_period - 1)]

        signals = []

        # MA crossover signal (momentum)
        if current_price > short_ma and short_ma > long_ma and prev_short_ma <= prev_long_ma:
            # Golden cross - buy
            signals.append(('buy', 0.6))
        elif current_price < short_ma and short_ma < long_ma and prev_short_ma >= prev_long_ma:
            # Death cross - sell
            signals.append(('sell', 0.6))

        # Check current position vs long MA
        if len(prices) >= 20:
            long_ma = self.calculate_ma(prices, 20)[-1]
            if current_price > long_ma * 1.02:
                if signals:
                    signals[0] = (signals[0][0], min(signals[0][1] + 0.2, 1.0))
                else:
                    signals.append(('buy', 0.3))
            elif current_price < long_ma * 0.98:
                if signals:
                    signals[0] = (signals[0][0], min(signals[0][1] + 0.2, 1.0))
                else:
                    signals.append(('sell', 0.3))

        # Volume confirmation
        if 'volume' in prices_history.get(stock_code, []):
            volumes = prices_history[stock_code]['volume']
            avg_volume = np.mean(volumes[-20:]) if len(volumes) >= 20 else np.mean(volumes)
            current_volume = volumes[-1] if volumes else 0

            if current_volume > avg_volume * self.volume_threshold:
                if signals:
                    signals[0] = (signals[0][0], min(signals[0][1] + 0.3, 1.0))
                else:
                    signals.append(('buy', 0.4))

        # Combine signals
        if not signals:
            return None, 0.0

        final_signal = signals[0]
        signal_strength = sum(s[1] for s in signals) / len(signals)
        signal_strength = min(signal_strength, 1.0)

        return final_signal, signal_strength

    def check_risk(self, current_price: float, entry_price: float) -> Optional[str]:
        """Check if risk control should trigger a trade."""
        trailing_stop_price = entry_price * (1 + self.trailing_stop) if entry_price > 0 else 0
        fixed_stop_price = entry_price * (1 - self.fixed_stop) if self.fixed_stop is not None and entry_price > 0 else 0

        # Check if price hit stop
        if self.fixed_stop is not None and current_price <= fixed_stop_price:
            return 'stop'

        if current_price <= trailing_stop_price:
            return 'stop'

        return 'hold'

    def get_position_size(self, portfolio: Portfolio, stock_code: str, current_price: float, 
                         signal_strength: float) -> int:
        """Calculate optimal position size."""
        max_single_value = self.initial_capital * self.max_single_position

        cash = portfolio.cash
        shares_value = 0.0

        for pos in portfolio.positions.values():
            if pos.stock_code != stock_code:
                if current_price and price > 0:
                    shares_value += pos.shares * pos.current_price

        position_value = min(cash + shares_value, max_single_value)

        # Calculate shares based on position value
        if current_price > 0:
            shares = int(position_value / current_price / 100) * 100
            return max(shares, 100)

        return 0


