"""
A-Share Paper Trading Skill Module
=================================

Complete paper trading simulation engine for A-share stocks.
This module provides:
- PaperTradingEngine: Manages virtual portfolio with proper A-share mechanics
- MomentumValueStrategy: Implements momentum-value hybrid trading strategy
- BacktestRunner: Runs strategies against historical market data

A-Share Rules Implemented:
- T+1 settlement (can't sell shares bought today until next trading day)
- Minimum lot size of 100 shares for buy orders
- Price limit validation (10% main board, 20% ChiNext/STAR, 5% ST stocks)
- Accurate fee calculation (commission, stamp tax, transfer fee)
"""

import json
import yaml
import os
from datetime import datetime, timedelta
from dataclasses import dataclass, field
from typing import Optional, Dict, List, Any, Tuple, Set
import pandas as pd
import numpy as np


# ============================================================================
# Data Structures
# ============================================================================

@dataclass
class Position:
    """Represents a stock position in the portfolio."""
    stock_code: str
    shares: int = 0
    avg_cost: float = 0.0
    current_price: float = 0.0
    purchased_date: str = ""
    bought_today: bool = False

    def calc_avg_price(self, new_price: float, shares_buy: int, shares_own: int) -> float:
        """Calculate new average cost after a purchase."""
        if shares_buy == 0:
            return self.avg_cost
        total_cost = (self.avg_cost * shares_own + new_price * shares_buy)
        return total_cost / (shares_own + shares_buy)

    def to_dict(self) -> Dict:
        return {
            'stock_code': self.stock_code,
            'shares': self.shares,
            'avg_cost': round(self.avg_cost, 2),
            'current_price': round(self.current_price, 2),
            'purchased_date': self.purchased_date,
            'bought_today': self.bought_today
        }


@dataclass
class Trade:
    """Represents a trade execution."""
    trade_id: str
    stock_code: str
    side: str
    shares: int
    fill_price: float
    fill_date: str
    fill_time: str
    amount: float
    commission: float
    stamp_tax: float
    transfer_fee: float
    total_cost: float
    order_type: str
    status: str
    reason: str = ""
    net_amount: float = 0.0

    def to_dict(self) -> Dict:
        return {
            'trade_id': self.trade_id,
            'stock_code': self.stock_code,
            'side': self.side,
            'shares': self.shares,
            'fill_price': round(self.fill_price, 2),
            'fill_date': self.fill_date,
            'fill_time': self.fill_time,
            'amount': round(self.amount, 2),
            'commission': round(self.commission, 2),
            'stamp_tax': round(self.stamp_tax, 2),
            'transfer_fee': round(self.transfer_fee, 2),
            'total_cost': round(self.total_cost, 2),
            'order_type': self.order_type,
            'status': self.status,
            'reason': self.reason,
            'net_amount': round(self.net_amount, 2)
        }


@dataclass
class Portfolio:
    """Represents the trading account/portfolio."""
    cash: float = 1000000.0
    trades: List[Trade] = field(default_factory=list)
    last_trade_date: str = ""
    positions: Dict[str, Position] = field(default_factory=dict)
    initial_capital: float = 1000000.0

    def add_trade(self, trade: Trade):
        self.trades.append(trade)

    def get_shares_value(self, prices: Dict[str, float]) -> float:
        """Calculate current value of shares held."""
        total = 0.0
        for pos in self.positions.values():
            if pos.stock_code in prices:
                share_price = prices[pos.stock_code]
                if isinstance(share_price, (int, float)) and share_price > 0:
                    total += pos.shares * share_price
        return total

    def get_total_equity(self, prices: Dict[str, float]) -> float:
        return self.cash + self.get_shares_value(prices)

    def get_initial_equity(self) -> float:
        return self.initial_capital

    def get_available_cash(self) -> float:
        """Get cash available for buying (excluding T+1 unsettled purchases)."""
        available = 0.0
        today = self.last_trade_date
        for trade in self.trades:
            if trade.fill_date == today and trade.side == 'sell' and trade.status == 'filled':
                available += trade.net_amount
            elif trade.fill_date != today and trade.side == 'buy' and trade.status == 'filled':
                # Funds from buys before today are available
                available += trade.net_amount
        return self.cash + available


