class BacktestRunner:
    """
    Backtest runner that executes strategy against historical data.
    """

    def __init__(self, strategy: MomentumValueStrategy, engine: PaperTradingEngine):
        self.strategy = strategy
        self.engine = engine

    def load_data(self, stocks: List[str]) -> Dict[str, pd.DataFrame]:
        """Load and prepare data for backtesting."""
        data = {}
        all_prices_history = {}
        all_trading_days = set()

        for stock_code in stocks:
            filepath = f"data/market/{stock_code}_daily.csv"
            if not os.path.exists(filepath):
                continue

            try:
                df = pd.read_csv(filepath)
                df = df.sort_values('date')

                data[stock_code] = df
                all_trading_days.update(df['date'].astype(str))

                # Store price history
                all_prices_history[stock_code] = df['close'].tolist()

            except Exception as e:
                print(f"Error loading {stock_code}: {e}")
                continue

        return data

    def is_trading_day(self, date: str) -> bool:
        return self.engine.is_trading_day(date)

    def run(self, stocks: List[str], start_date: str = None) -> Dict:
        """Run backtest for the specified stocks."""
        print(f"Backtesting {len(stocks)} stocks...")

        # Get all trading days
        all_trading_days = set()
        for sc in stocks:
            filepath = f"data/market/{sc}_daily.csv"
            if os.path.exists(filepath):
                df = pd.read_csv(filepath)
                all_trading_days.update(df['date'].astype(str))

        trading_days = sorted([str(d) for d in all_trading_days])

        # Get initial prices for all stocks on start date
        initial_date = start_date if start_date and self.is_trading_day(start_date) else None

        engine = PaperTradingEngine(initial_capital=self.strategy.initial_capital)

        if initial_date:
            engine.portfolio.last_trade_date = initial_date

        prices = {}
        for sc in stocks:
            filepath = f"data/market/{sc}_daily.csv"
            if os.path.exists(filepath):
                df = pd.read_csv(filepath)
                if initial_date:
                    mask = df['date'] == initial_date
                    if mask.sum() > 0:
                        prices[sc] = float(df.loc[mask, 'close'].values[0])
                elif len(df) > 0:
                    prices[sc] = float(df['close'].iloc[0])

        # Place initial buy orders for all stocks
        for sc, price in prices.items():
            if price > 0:
                try:
                    engine.place_order(sc, 'buy', price, 100, initial_date if initial_date else trading_days[0] if trading_days else "2023-01-03", time='14:57', order_type='market_order_at_close')
                except Exception as e:
                    print(f"Error placing order for {sc}: {e}")

        # Run simulation day by day
        results = {
            'total_return': 0.0,
            'total_trades': 0,
            'win_rate': 0.0,
            'max_drawdown': 0.0,
            'sharpe_ratio': 0.0,
            'trade_log': [],
            'daily_returns': [],
            'portfolio_values': []
        }

        initial_equity = engine.portfolio.initial_capital
        current_equity = initial_equity

        for day in trading_days:
            if not self.is_trading_day(day):
                continue

            engine.portfolio.last_trade_date = day

            # Get current prices
            prices = {}
            for sc in stocks:
                filepath = f"data/market/{sc}_daily.csv"
                if os.path.exists(filepath):
                    df = pd.read_csv(filepath)
                    mask = df['date'] == day
                    if mask.sum() > 0:
                        prices[sc] = float(df.loc[mask, 'close'].values[0])

            # Get current portfolio value
            portfolio_value = engine.portfolio.get_total_equity(prices)
            results['portfolio_values'].append((day, portfolio_value))

            # Track initial equity
            if results['portfolio_values']:
                initial_value = results['portfolio_values'][0][1]

            # Calculate returns
            if results['daily_returns']:
                prev_value = results['portfolio_values'][-1][1]
                if prev_value > 0:
                    return_pct = (portfolio_value - prev_value) / prev_value
                    results['daily_returns'].append((day, return_pct))

            # Make trading decisions
            self._trade_on_day(day, prices, engine, results)

        # Calculate final metrics
        results['total_trades'] = len(engine.portfolio.trades)

        final_equity = engine.portfolio.get_total_equity(prices)
        results['total_return'] = (final_equity - initial_equity) / initial_equity if initial_equity > 0 else 0

        return results

    def _trade_on_day(self, date: str, prices: Dict[str, float], engine: PaperTradingEngine, results: Dict):
        """Execute trading decisions for the current day."""
        positions = engine.get_positions_for_date(date)

        for stock_code, price in prices.items():
            if price <= 0:
                continue

            # Skip if already hold this stock
            if stock_code in positions and positions[stock_code] > 0:
                continue

            # Check if stock is in our universe
            if stock_code not in engine.stock_list:
                continue

            # Get signal
            signal, strength = self.strategy.calculate_signals(stock_code, price, {})

            if signal is None or strength < 0.3:
                continue

            # Check risk controls
            if stock_code in engine.portfolio.positions:
                pos = engine.portfolio.positions[stock_code]
                risk_action = self.strategy.check_risk(price, pos.avg_cost)

                if risk_action == 'stop':
                    # Sell if we own
                    pos_shares = engine.portfolio.positions[stock_code].shares
                    try:
                        engine.place_order(stock_code, 'sell', price, pos_shares, date, time='09:30')
                    except:
                        pass
                continue

            # Get position size
            position_size = self.strategy.get_position_size(engine.portfolio, stock_code, price, strength)

            if signal[0] == 'buy':
                today_date = date
                try:
                    engine.place_order(stock_code, 'buy', price, position_size, today_date, time='14:57', order_type='market_order_at_close')
                except Exception as e:
                    print(f"Error buying {stock_code}: {e}")

    def calculate_metrics(self, results: Dict) -> Dict:
        """Calculate performance metrics."""
        if not results['portfolio_values']:
            return results

        values = [v for d, v in results['portfolio_values']]
        initial_value = values[0]
        final_value = values[-1]

        # Calculate returns
        returns = []
        current = initial_value
        for v in values:
            if current > 0:
                returns.append((v - current) / current)
            current = v

        # Max drawdown
        peak = values[0]
        max_dd = 0.0
        for v in values:
            if v > peak:
                peak = v
            dd = (peak - v) / peak if peak > 0 else 0
            if dd > max_dd:
                max_dd = dd

        # Sharpe ratio
        if len(returns) > 1:
            mean_return = np.mean(returns)
            std_return = np.std(returns)
            if std_return > 0:
                sharpe = (mean_return / std_return) * np.sqrt(252)
            else:
                sharpe = 0
        else:
            sharpe = 0

        # Win rate
        winning = sum(1 for r in returns if r > 0)
        win_rate = winning / len(returns) if len(returns) > 0 else 0

        results['total_return'] = results.get('total_return', 0)
        results['max_drawdown'] = max_dd
        results['sharpe_ratio'] = sharpe
        results['win_rate'] = win_rate
        results['daily_returns'] = returns

        return results

    def generate_summary(self, results: Dict) -> str:
        """Generate a human-readable summary."""
        summary = """
================================================================================
                    PAPER TRADING BACKTEST RESULTS
================================================================================

Performance Metrics:
-------------------
Total Return: {:.2f}%
Total Trades: {}
Win Rate: {:.2f}%
Max Drawdown: {:.2f}%
Sharpe Ratio: {:.3f}
""".format(
            results.get('total_return', 0) * 100,
            results.get('total_trades', 0),
            results.get('win_rate', 0) * 100,
            results.get('max_drawdown', 0) * 100,
            results.get('sharpe_ratio', 0)
        )

        summary += """
