if __name__ == "__main__":
    # Load strategy parameters
    try:
        strategy_params = load_yaml_file('config/strategy_params.yaml')
    except Exception as e:
        print(f"Error loading strategy params: {e}")
        strategy_params = {
            'position_management': {'initial_capital': 1000000},
            'stock_selection': {'ma_periods': [5, 10, 20]}
        }

    # Get initial capital
    initial_capital = strategy_params.get('position_management', {}).get('initial_capital', 1000000)

    # Create engine and strategy
    engine = PaperTradingEngine(initial_capital=initial_capital)
    strategy = MomentumValueStrategy(params=strategy_params)

    # Get available stocks
    stocks = []
    market_dir = 'data/market'
    if os.path.exists(market_dir):
        for filename in os.listdir(market_dir):
            if filename.endswith('_daily.csv'):
                stocks.append(filename.replace('_daily.csv', ''))

    print(f"\nFound {len(stocks)} stocks in market data directory")
    print("\n" + "=" * 80)
    print("PAPER TRADING BACKTEST")
    print("=" * 80)
    print(f"Initial Capital: {initial_capital:,.2f} CNY")
    print(f"Stocks to backtest: {', '.join(stocks)}")
    print("=" * 80)

    # Run backtest
    runner = BacktestRunner(strategy, engine)
    results = runner.run(stocks)

    # Calculate and display metrics
    final_results = runner.calculate_metrics(results)
    print(runner.generate_summary(final_results))

    print("=" * 80)
    print("BACKTEST COMPLETED")
    print("=" * 80)
